const names={games:'Oyun çarkı',pool:'Görev havuzu',wishes:'Ödül istekleri',daily:'Günlük görevler',progress:'Çocuk takibi',account:'Profil ayarları',admin:'Admin paneli',approvals:'Onaylar',home:'Aile panosu',profile:'Sayfam',competitions:'Yarışmalar',tasks:'Görevler',wheel:'Çarkıfelek',rewards:'Ödüller',history:'Hareketler',settings:'Ayarlar'};
const periods={daily:'1 gün',weekly:'1 hafta',monthly:'1 ay'};
let setupMode=false, adminTab='tasks', adminPerson='', state, csrf='', selected=localStorage.getItem('homedojo-profile')||'u1', page='home', filter='all', busy=false, spinning=false, wheelAngle=0, wheelTasks=[], toastTimer, refreshTimer, clockOffset=0, wheelFilter='all';
// Audio starts only after a user gesture; unsupported browsers keep the wheel silent.
const wheelSound=(()=>{
 let enabled=true,context,frame=0,nodes=new Set();
 try{enabled=localStorage.getItem('homedojo-wheel-sound')!=='off';}catch{}
 function unlock(){
  if(!enabled)return;
  try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;context ||= new Audio();if(context.state==='suspended')context.resume().catch(()=>{});}catch{}
 }
 function tone(frequency,delay=0,length=.035,volume=.075){
  if(!enabled||document.hidden||context?.state!=='running')return;
  try{
   const oscillator=context.createOscillator(),gain=context.createGain(),start=context.currentTime+delay;
   oscillator.type='sine';oscillator.frequency.setValueAtTime(frequency,start);oscillator.frequency.exponentialRampToValueAtTime(frequency*.55,start+length);
   gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(volume,start+.003);gain.gain.exponentialRampToValueAtTime(.0001,start+length);
   oscillator.connect(gain);gain.connect(context.destination);nodes.add(oscillator);
   oscillator.onended=()=>{nodes.delete(oscillator);oscillator.disconnect();gain.disconnect();};oscillator.start(start);oscillator.stop(start+length+.01);
  }catch{}
 }
 function stop(){cancelAnimationFrame(frame);frame=0;for(const node of nodes){try{node.stop();}catch{}}nodes.clear();}
 function follow(element,count){
  stop();let previous=null,travel=0,lastTick=-Infinity;const step=360/count;
  function tick(now){
   if(document.hidden||!element.isConnected){stop();return;}
   const transform=getComputedStyle(element).transform;
   const matrix=new DOMMatrixReadOnly(transform==='none'?undefined:transform),angle=Math.atan2(matrix.b,matrix.a)*180/Math.PI;
   if(previous!==null){const delta=(angle-previous+540)%360-180,old=Math.floor(travel/step);travel+=Math.max(0,delta);if(Math.floor(travel/step)>old&&now-lastTick>=45){tone(1500);lastTick=now;}}
   previous=angle;frame=requestAnimationFrame(tick);
  }
  // Seed the angle before the first animation frame so fast initial movement is included.
  tick(performance.now());
 }
 function finish(){stop();[660,880,1320].forEach((note,i)=>tone(note,i*.11,.24,.065));}
 function toggle(){enabled=!enabled;try{localStorage.setItem('homedojo-wheel-sound',enabled?'on':'off');}catch{}if(enabled)unlock();else for(const node of nodes){try{node.stop();}catch{}}return enabled;}
 return{unlock,follow,finish,stop,toggle,get enabled(){return enabled;}};
})();
function soundButton(){return `<span aria-hidden="true">${wheelSound.enabled?'♫':'♪'}</span> Ses ${wheelSound.enabled?'açık':'kapalı'}`;}
document.addEventListener('visibilitychange',()=>{if(document.hidden)wheelSound.stop();});
window.addEventListener('pagehide',()=>wheelSound.stop());
function wishEffect(title,detail,glyph='🎁'){
 document.querySelector('.wish-celebration')?.remove();
 const box=document.createElement('aside');box.className='wish-celebration';box.setAttribute('role','status');
 box.innerHTML=`<div class="wish-orbit" aria-hidden="true"><span>✦</span><b>${esc(glyph)}</b><span>✧</span></div><strong>${esc(title)}</strong><p>${esc(detail)}</p><button class="text-button">Harika! ✨</button>`;
 box.querySelector('button').onclick=()=>box.remove();document.body.append(box);wheelSound.finish();celebrate();setTimeout(()=>box.remove(),6500);
}
function rewardWishesPanel(){
 const child=user().memberType==='child',rows=(state.rewardWishes||[]).slice().reverse(),pending=rows.filter(w=>w.status==='pending');
 const card=w=>{const name=state.users.find(u=>u.id===(child?w.parentId:w.childId))?.name||'Aile üyesi',labels={pending:'Yanıt bekliyor',approved:'Hayalin bir hedef oldu',declined:'Şimdilik uygun değil',cancelled:'Geri çekildi'};
 return `<article class="wish-card ${w.status}"><span class="wish-card-icon" aria-hidden="true">${esc(w.icon)}</span><div class="wish-card-copy"><span class="eyebrow">${esc(name)} · ${labels[w.status]}</span><h3>${esc(w.title)}</h3>${w.description?`<p>${esc(w.description)}</p>`:''}${w.note?`<p class="wish-note">${esc(w.note)}</p>`:''}${w.cost?`<strong class="points">✦ ${number(w.cost)} puan</strong>`:''}</div>${w.status==='pending'?child?`<button class="text-button" data-cancel-wish="${w.id}">Geri çek</button>`:`<button class="primary" data-review-wish="${w.id}">Puan belirle ${icon('arrow')}</button>`:!child?`<button class="text-button" data-delete-wish="${w.id}" aria-label="${esc(w.title)} isteğini sil">${icon('trash')} Sil</button>`:''}</article>`;};
 return `<section class="wish-hero"><div class="wish-hero-art" aria-hidden="true"><span>✦</span>🎁<span>✧</span></div><div><div class="eyebrow">${child?'HAYAL ET · ADIM AT · BAŞAR':'KÜÇÜK EMEKLER, BÜYÜK HAYALLER'}</div><h2>${child?'Bir hayalin mi var?':'Bir hedefle cesaretlendir.'}</h2><p>${child?'Ödülünü iste. Ebeveynin puanını belirlesin, görevlerin seni hayaline yaklaştırsın.':'Çocuğun istediği ödüle ulaşılabilir bir puan belirle. Onaylanan ödül, onun yeni hedefi olur.'}</p></div><div class="wish-hero-actions">${child?'<button class="primary" data-action="new-wish">✦ Ödül iste</button>':''}<button class="text-button" data-action="toggle-sound" aria-label="Efekt sesleri" aria-pressed="${wheelSound.enabled}">${soundButton()}</button></div></section>${child&&user().goal?goalPanel():''}<div class="section-heading"><h2>${child?'İsteklerin':'Bekleyen ödül istekleri'}</h2><span class="quiet">${pending.length} bekliyor</span></div><div class="wish-list">${pending.map(card).join('')||'<div class="panel empty">Henüz bekleyen bir istek yok. ✨</div>'}</div>${rows.some(w=>w.status!=='pending')?`<details class="wish-history"><summary>Önceki istekler</summary><div class="wish-list">${rows.filter(w=>w.status!=='pending').map(card).join('')}</div></details>`:''}`;
}
function deleteRewardRequestEditor(id){
 const wish=state.rewardWishes.find(w=>w.id===id);if(!wish)return;
 openModal('Eski isteği sil',`<p><strong>${esc(wish.title)}</strong> isteği senin listenden kaldırılacak. Çocuğun isteği, hedef ödülü ve puanları korunur.</p><div class="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-close>Vazgeç</button><button class="danger" id="delete-wish-confirm">Listemden sil</button></div>`);
 $('#delete-wish-confirm').onclick=()=>commit('deleteRewardRequest',{id},'Eski istek listenden kaldırıldı.');
}
function requestRewardEditor(){
 const parents=state.users.filter(u=>u.memberType==='parent');
 openModal('Hayalindeki ödül ✨',`<form id="wish-form"><div class="wish-form-gift" aria-hidden="true">🎁</div><label>Ne kazanmak istersin?<input name="title" maxlength="80" placeholder="Örneğin: Birlikte sinemaya gitmek" required></label><label>Küçük bir not<textarea name="description" maxlength="240" placeholder="Bu ödül seni neden mutlu eder?"></textarea></label><div class="form-grid"><label>Simgesi<select name="icon">${['🎁','🎮','🚲','🎬','🧸','📚','🎨','⚽','🍦','🏕️'].map(i=>`<option>${i}</option>`).join('')}</select></label><label>Hangi ebeveyne?<select name="parentId" required>${parents.map(p=>`<option value="${p.id}" ${p.id===user().guardianId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><p class="field-hint">Puanı ebeveynin belirleyecek. Onaylanınca yeni hedefin olacak.</p><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-close>Vazgeç</button><button class="primary" ${parents.length?'':'disabled'}>Hayalimi gönder ✨</button></div></form>`);
 const requestId=crypto.randomUUID();$('#wish-form').onsubmit=e=>{e.preventDefault();wheelSound.unlock();commit('requestReward',{...Object.fromEntries(new FormData(e.target)),requestId},'Ödül isteğin gönderildi.');};
}
function reviewRewardEditor(id){
 const w=state.rewardWishes.find(w=>w.id===id),child=state.users.find(u=>u.id===w.childId);
 openModal('Bir hayale hedef belirle',`<form id="wish-review"><div class="wish-form-gift" aria-hidden="true">${esc(w.icon)}</div><h3>${esc(w.title)}</h3><p>${esc(child?.name)}${w.description?' · '+esc(w.description):''}</p><p class="field-hint">Mevcut puanı: ${number(child?.balance||0)}. Onaylanan ödül çocuğun yeni hedefi olacak.</p><label>Puan hedefi<input type="number" name="cost" min="1" max="100000" step="1" placeholder="Örneğin 200" required></label><label>Cesaret veren bir not<textarea name="note" maxlength="240" placeholder="Küçük adımlarla başarabilirsin!"></textarea></label><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="text-button" id="decline-wish">Şimdilik uygun değil</button><button class="primary">Onayla ve hedef yap ✦</button></div></form>`);
 $('#wish-review').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));wheelSound.unlock();commit('reviewRewardRequest',{id,decision:'approve',cost:Number(data.cost),note:data.note},'Ödül onaylandı ve çocuğun hedefi oldu.');};
 $('#decline-wish').onclick=()=>commit('reviewRewardRequest',{id,decision:'decline',note:$('#wish-review [name="note"]').value},'Yanıtın çocuğa iletildi.');
}

document.addEventListener('pointerdown',()=>wheelSound.unlock(),{once:true});
document.addEventListener('keydown',()=>wheelSound.unlock(),{once:true});
const user=()=>state.users.find(u=>u.id===selected)||state.users[0];
const number=n=>n.toLocaleString('tr-TR');
async function api(action,data){
  const response=await fetch(`api.php?action=${action}`,data===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(data)});
  let body;try{body=await response.json();}catch{throw new Error('Sunucuya ulaşılamadı. Bağlantını kontrol edip yeniden dene.');}
  if(!response.ok){if(response.status===401){const fresh=await fetch('api.php?action=session',{cache:'no-store'});const session=await fresh.json();csrf=session.csrf;setupMode=session.needsAccountSetup;showLogin();}throw new Error(body.error||'İşlem tamamlanamadı.');}
  return body;
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;$('#confetti').innerHTML=Array.from({length:42},()=>`<i class="confetto" style="left:${Math.random()*100}%;background:${colors[Math.floor(Math.random()*4)]};animation-delay:${Math.random()*.3}s;transform:rotate(${Math.random()*360}deg)"></i>`).join('');setTimeout(()=>$('#confetti').replaceChildren(),2400);}

function acceptState(next){const previous=state?.viewerId===next.viewerId?state.users.find(u=>u.id===next.viewerId):null;const upcoming=next.users.find(u=>u.id===next.viewerId);if(previous&&upcoming?.memberType==='child'){const gain=upcoming.balance-previous.balance;if(gain>0)queueMicrotask(()=>wishEffect(`+${number(gain)} puan!`,'Her küçük adım bir başarı.','⭐'));}state=next;selected=state.viewerId;if(adminPerson!=='shared'&&!state.users.some(u=>u.id===adminPerson))adminPerson=selected;clockOffset=Date.parse(next.serverNow)-Date.now();}
const serverTime=()=>Date.now()+clockOffset;
const assignmentStatus=a=>['completed','cancelled','pending'].includes(a.status)?a.status:a.noDeadline?'active':Date.parse(a.dueAt)<=serverTime()?'expired':'active';
const eligibleTasks=()=>state.tasks.filter(t=>(user().eligibleTaskIds||[]).includes(t.id));
const formatDeadline=at=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Istanbul'}).format(new Date(at));
function remaining(at){let sec=Math.max(0,Math.ceil((Date.parse(at)-serverTime())/1000));if(!sec)return 'Süre doldu · 0 puan';const days=Math.floor(sec/86400);sec%=86400;const hours=Math.floor(sec/3600),minutes=Math.floor(sec%3600/60),seconds=sec%60;return `${days?days+' gün ':''}${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')} kaldı`;}
function goalPanel(){const goal=user().goal;if(!goal)return '';if(!goal&&state.familyGoal)return `<section class="goal-banner"><div class="goal-emoji">${esc(state.familyGoal.icon)}</div><div class="goal-copy"><div class="eyebrow">ORTAK ÖDÜLÜMÜZ</div><h2>${esc(state.familyGoal.prize)}</h2><p>Aile yarışması başladı. Çarktan görev alarak ortak hedefe katkıda bulun!</p></div><button class="primary" data-nav="wheel">Çarktan görev al</button></section>`;if(!goal)return `<section class="goal-banner no-goal"><div class="goal-emoji">🎯</div><div class="goal-copy"><div class="eyebrow">1 · HAYALİNİ SEÇ</div><h2>Sen hangi ödül için oynuyorsun?</h2></div><button class="primary" data-nav="rewards">${icon('gift')} Hedef ödül seç</button></section>`;const pct=Math.min(100,Math.floor(user().balance*100/goal.cost)),left=Math.max(0,goal.cost-user().balance);return `<section class="goal-banner"><div class="goal-emoji">${esc(goal.icon)}</div><div class="goal-copy"><div class="eyebrow">${esc(user().name)} · HEDEF ÖDÜLÜM</div><h2>${esc(goal.title)} ${left===0?'🎉':''}</h2><p>${left?`${number(left)} puan kaldı.`:'Başardın! Biriktirdiğin puanlarla ödülünü alabilirsin.'}</p><div class="goal-meter"><div class="progress" role="progressbar" aria-label="Hedef ödül ilerlemesi" aria-valuemin="0" aria-valuemax="${goal.cost}" aria-valuenow="${Math.min(user().balance,goal.cost)}"><span style="width:${pct}%"></span></div><strong>${number(user().balance)} / ${number(goal.cost)} puan · %${pct}</strong></div></div><div class="goal-actions">${left===0?`<button class="primary" data-redeem="${goal.id}">${icon('gift')} Ödülümü al</button>`:`<button class="primary" data-nav="wheel">${icon('wheel')} Görev kazan</button>`}</div></section>`;}
function assignmentsPanel(){
 const items=state.assignments.filter(a=>a.userId===selected&&!a.routineId&&['active','pending'].includes(assignmentStatus(a))).reverse();
 return `<section class="assigned-section"><div class="section-heading"><h2>Görevlerim <span class="badge">${items.length}</span></h2><button class="text-button" data-nav="history">Geçmiş</button></div><div class="assignment-grid">${items.map(a=>{const pending=a.status==='pending',reviewer=state.users.find(u=>u.id===a.reviewerId);return `<article class="assignment-card" ${pending||a.noDeadline?'':`data-assignment-card="${a.id}" data-deadline="${esc(a.dueAt)}"`}><div class="assignment-top"><span class="task-icon">${esc(a.icon)}</span><span class="assignment-points">+${number(a.points)} <small>puan</small></span></div><h3>${esc(a.title)}</h3>${a.description?`<p>${esc(a.description)}</p>`:''}${pending?`<div class="pending-note">${esc(reviewer?.name)} onayı bekleniyor</div>`:` ${a.noDeadline?'':`<div class="assignment-timer" data-countdown="${esc(a.dueAt)}">${remaining(a.dueAt)}</div>`}${a.rejectedAt?'<p class="review-note">Ebeveynin geri gönderdi. Düzenleyip tekrar onaya gönderebilirsin.</p>':''}<button class="primary" data-complete="${a.id}">${icon('check')} Tamamladım</button><button class="cancel-task" data-cancel-assignment="${a.id}">Görevi iptal et</button>`}<details class="task-details"><summary>Ayrıntılar</summary><p>${a.noDeadline?'Süre sınırı yok':`${periods[a.frequency]} · Son tarih: ${formatDeadline(a.dueAt)}`}<br>Hedef: ${esc(a.goalTitle)}</p></details></article>`;}).join('')||'<div class="empty">Aktif görevin yok. Çarktan yeni bir görev al.</div>'}</div></section>`;
}

function tickDeadlines(){document.querySelectorAll('[data-countdown]').forEach(el=>{el.textContent=el.dataset.competitionTimer!==undefined&&Date.parse(el.dataset.countdown)<=serverTime()?'Yarışma süresi doldu':remaining(el.dataset.countdown);});document.querySelectorAll('[data-assignment-card]').forEach(card=>{if(Date.parse(card.dataset.deadline)<=serverTime()){card.classList.add('expired');const b=card.querySelector('[data-complete]');if(b){b.disabled=true;b.textContent='Süre doldu · puan verilmedi';}}});}
setInterval(tickDeadlines,1000);

function profileCards(){
 const rows=[...state.users].sort((a,b)=>b.earned-a.earned);
 return `<div class="players score-cards">${rows.map((u,i)=>`<article class="player ${u.id===selected?'selected':''}" style="--accent:${colors[i]}"><div class="player-top"><span class="avatar">${avatarMarkup(u)}</span><div><div class="player-name">${esc(u.name)} ${u.id===selected?'<small>Sen</small>':''}</div><div class="player-level">${rows.findIndex(x=>x.earned===u.earned)+1}. sıra</div></div></div><div class="player-score">${number(u.earned)} <span>puan</span></div><div class="player-foot"><span>${number(u.balance)} kullanılabilir</span></div></article>`).join('')}</div>`;
}

const adminTaskVisible=t=>adminPerson==='shared'?t.scope==='shared':t.ownerId===adminPerson||(t.scope==='shared'&&t.participantIds.includes(adminPerson));
function taskRows(){const tasks=state.tasks.filter(t=>adminTaskVisible(t)&&(filter==='all'||t.frequency===filter));return tasks.length?tasks.map(t=>{const completed=false,active=(state.assignments||[]).some(a=>a.userId===selected&&a.taskId===t.id&&assignmentStatus(a)==='active');return `<div class="task-row ${completed?'done':''}"><div class="task-icon">${esc(t.icon)}</div><div class="task-info"><h3>${esc(t.title)} ${t.scope==='shared'?'<span class="shared-badge">Ortak</span>':''}</h3><p><span class="type">${periods[t.frequency]}</span> · ${esc(t.description)}</p></div><span class="points">${icon('star')} +${number(t.points)}</span><span class="badge task-state">${completed?'Tamamlandı':active?'Atandı':'Çarkta'}</span><div class="task-actions"><button class="icon-button" data-edit-task="${t.id}" aria-label="${esc(t.title)} düzenle">${icon('edit')}</button>${page==='admin'?`<button class="icon-button" data-delete-task="${t.id}" aria-label="${esc(t.title)} sil">${icon('trash')}</button>`:''}</div></div>`;}).join(''):'<div class="empty">Burada henüz görev yok.<br>Eklediğin her görev çarkta bir dilim olacak! ✨</div>';}
function tasksPanel(){return `<div class="section-heading"><h2>Görev havuzu</h2><button class="primary" data-action="new-task">${icon('plus')} Görev ekle</button></div><section class="panel"><div class="tabs" role="group" aria-label="Görev dönemi">${[['all','Tümü'],...Object.entries(periods)].map(([v,label])=>`<button data-filter="${v}" class="${filter===v?'active':''}" aria-pressed="${filter===v}">${label}</button>`).join('')}</div><div class="task-list">${taskRows()}</div></section>`;}
function wheelPanel(immersive=false){
 const tasks=eligibleTasks();
 return `<section class="panel wheel-panel ${immersive?'wheel-immersive':''}" aria-label="Görev çarkı">
  <div class="wheel-head"><div class="eyebrow">BİRAZ ŞANS · BÜYÜK BİR BAŞLANGIÇ</div><h2>Bugünün sürprizi <span>çarkta.</span></h2><p>Çarkı çevir, görevini keşfet.</p></div>
  <div class="wheel-wrap"><div class="wheel-aura" aria-hidden="true"></div><div class="wheel-orbit" aria-hidden="true"></div><span class="wheel-spark s1" aria-hidden="true">✦</span><span class="wheel-spark s2" aria-hidden="true">✧</span><span class="wheel-spark s3" aria-hidden="true">✦</span><div class="wheel-rim"></div><div class="wheel-lights" aria-hidden="true">${Array.from({length:48},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="wheel" id="wheel"><canvas id="wheel-canvas" width="1200" height="1200" aria-label="Görev adları ve puanlarını gösteren çark"></canvas></div><div class="wheel-center" aria-hidden="true"><span>✦</span><small>HOME<br>DOJO</small></div><div class="pointer" aria-hidden="true"></div></div>
  <div class="wheel-controls"><button class="wheel-sound" data-action="toggle-sound" aria-label="Çark sesi" aria-pressed="${wheelSound.enabled}">${soundButton()}</button><div id="wheel-result" class="wheel-result" role="status">${tasks.length?`<span class="live-dot"></span> ${tasks.length} görev · Bir sonraki başarı senin`:'Bu dönemde seçilebilecek görev kalmadı.'}</div><button class="primary spin-button" data-action="spin" ${!tasks.length?'disabled':''}>${icon('wheel')} <span>Çarkı çevir</span> ${icon('arrow')}</button><p class="wheel-note">Çevir. Görevini keşfet. Tamamla, ebeveynine onaya gönder.</p></div>
  <details class="wheel-legend"><summary>Çarktaki görevleri keşfet · ${tasks.length}</summary><ol>${tasks.map(t=>`<li><span>${esc(t.icon)} ${esc(t.title)}</span><strong>+${number(t.points)}</strong></li>`).join('')||'<li>Yeni görevleri ebeveynin ekleyebilir.</li>'}</ol></details>
 </section>`;
}
function wheelExperience(){
 const goal=null,progress=0;
 return `<main class="wheel-experience"><header class="wheel-toolbar"><button class="stage-back" data-nav="profile">${icon('arrow')}<span>Ana sayfa</span></button><a href="#" class="brand" data-nav="profile"><span class="brand-icon">⌂</span><div>home<span>dojo</span></div></a><button class="top-profile" data-nav="profile"><span class="mini-avatar">${avatarMarkup(user())}</span>${esc(user().name)}${icon('down')}</button></header>${wheelPanel(true)}<div class="stage-target">${goal?`${esc(goal.icon)} <span>Hedefim: <strong>${esc(goal.title)}</strong></span><span>${number(progress)} / ${number(goal.cost)} puan</span>`:'Her küçük görev, yepyeni bir başarı.'}</div></main>`;
}
function drawWheel(candidates,winningId=null,games=false){
 wheelTasks=candidates||eligibleTasks();const canvas=$('#wheel-canvas');if(!canvas)return;
 const ctx=canvas.getContext('2d'),list=wheelTasks.length?wheelTasks:[{icon:'✨',points:0,title:'Yeni görev ekle'}],n=list.length,c=600;
 ctx.clearRect(0,0,1200,1200);
 const shades=[['#c3a1ff','#8060d1'],['#ffbadf','#c371ac'],['#ffe1a3','#d3a25b'],['#b7edd1','#70b5a0'],['#b6c9ff','#788bcb'],['#eab4ff','#aa72cc'],['#ffc8b2','#d39178'],['#d0eba4','#92b568'],['#a5e2eb','#65a4b8'],['#e6b6cf','#ad7e9f']];
 for(let i=0;i<n;i++){
  const a=-Math.PI/2+i*2*Math.PI/n,b=a+2*Math.PI/n,isWinner=list[i].id===winningId;
  const gradient=ctx.createRadialGradient(c,c,80,c,c,c),shade=shades[i%shades.length];gradient.addColorStop(0,shade[1]);gradient.addColorStop(1,shade[0]);
  ctx.beginPath();ctx.moveTo(c,c);ctx.arc(c,c,c-3,a,b);ctx.closePath();ctx.fillStyle=gradient;ctx.fill();ctx.strokeStyle='#2b194d80';ctx.lineWidth=3;ctx.stroke();
  if(isWinner){ctx.fillStyle='#fff5';ctx.fill();ctx.strokeStyle='#fff2c4';ctx.lineWidth=12;ctx.stroke();}
  ctx.save();ctx.translate(c,c);ctx.rotate((a+b)/2);ctx.translate(n>16?490:405,0);ctx.rotate(Math.PI/2);ctx.fillStyle='#261539';ctx.textAlign='center';
  if(n<=16){
   ctx.font='47px sans-serif';ctx.fillText(list[i].icon,0,-66);ctx.font=`800 ${n<=10?36:28}px sans-serif`;
   const maxWidth=n<=10?218:146,words=list[i].title.split(' '),lines=[''];
   for(const word of words){const j=lines.length-1,trial=(lines[j]+' '+word).trim();if(ctx.measureText(trial).width<=maxWidth)lines[j]=trial;else lines.push(word);}
   let labels=lines.filter(Boolean).slice(0,2);labels=labels.map((line,j)=>{let value=line;while(ctx.measureText(value).width>maxWidth&&value.length>1)value=value.slice(0,-1);if(value!==line||(j===1&&lines.length>2))value=value.slice(0,-1)+'…';return value;});
   labels.forEach((line,j)=>ctx.fillText(line,0,-14+j*39));ctx.font='800 39px sans-serif';if(!games)ctx.fillText('+'+list[i].points,0,81);
  }else{ctx.font='bold 30px sans-serif';ctx.fillText(String(i+1),0,0);}
  ctx.restore();
 }
 const gloss=ctx.createLinearGradient(0,0,1200,1200);gloss.addColorStop(0,'#ffffff32');gloss.addColorStop(.45,'#ffffff00');gloss.addColorStop(1,'#10051c18');ctx.beginPath();ctx.arc(c,c,c-3,0,Math.PI*2);ctx.fillStyle=gloss;ctx.fill();
 $('#wheel').style.transition='none';$('#wheel').style.transform=`rotate(${wheelAngle}deg)`;
}
function rewardsPanel(full=false){const rewards=state.rewards.filter(r=>r.ownerId===selected);return `${user().memberType==='child'?'<div class="wish-shortcut"><span>Hayalindeki ödül burada yok mu?</span><button class="primary" data-action="new-wish">✦ Ödül iste</button></div>':''}<div class="section-heading"><div><h2>Emeklerinin tatlı karşılığı 🎁</h2>${full?'<p style="margin-top:8px">Puanlarını biriktir, kendine bir güzellik yap.</p>':''}</div><button class="text-button" ${page==='admin'?'data-action="new-reward"':'data-nav="profile"'}>${page==='admin'?'Ödül ekle':'Sayfama dön'} ${icon(full?'plus':'arrow')}</button></div><div class="reward-grid">${rewards.length?rewards.slice(0,full?100:4).map((r,i)=>{const pct=Math.min(100,user().balance/r.cost*100),enough=user().balance>=r.cost;return `<article class="reward-card" style="--accent:${colors[i%4]}"><div class="reward-art"><span aria-hidden="true">${esc(r.icon)}</span><div class="reward-cost">✧ ${number(r.cost)} puan</div></div><div class="reward-body"><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><button class="goal-select ${user().goal?.id===r.id?'chosen':''}" data-goal="${r.id}" ${user().goal?.id===r.id?'disabled':''}>${user().goal?.id===r.id?'✓ Hedef ödülüm':'🎯 Hedef olarak seç'}</button><div class="progress"><span style="width:${pct}%"></span></div><div class="reward-footer"><span>${enough?'Senin olabilir!':`${number(r.cost-user().balance)} puan kaldı`}</span><button class="redeem" data-redeem="${r.id}" ${enough?'':'disabled'}>${icon(enough?'gift':'lock')}${enough?'Ödülü al':'Kilitli'}</button></div>${page==='admin'?`<div class="task-actions" style="margin-top:12px;display:flex"><button class="text-button" data-edit-reward="${r.id}">${icon('edit')} Düzenle</button><button class="icon-button" style="margin-left:auto" data-delete-reward="${r.id}" aria-label="${esc(r.title)} sil">${icon('trash')}</button></div>`:''}</div></article>`;}).join(''):'<div class="empty">Henüz sana özel bir ödül eklenmedi. 🎁</div>'}</div>`;}
function historyPanel(){const failures=(state.assignments||[]).filter(a=>a.userId===selected&&['expired','cancelled'].includes(assignmentStatus(a))).map(a=>({...a,at:a.cancelledAt||a.dueAt,delta:0,kind:assignmentStatus(a)}));const events=[...state.completions.filter(c=>c.userId===selected).map(c=>({...c,delta:c.points,kind:'complete'})),...state.redemptions.filter(c=>c.userId===selected).map(c=>({...c,delta:-c.cost,kind:'reward'})),...failures].sort((a,b)=>b.at.localeCompare(a.at));return `<div class="stats-grid"><div class="panel stat"><strong>${number(user().earned)}</strong><span class="quiet">Kazanılan toplam puan</span></div><div class="panel stat"><strong>${number(user().balance)}</strong><span class="quiet">Kullanılabilir puan</span></div><div class="panel stat"><strong>${failures.length}</strong><span class="quiet">İptal / süre aşımı · puan verilmedi</span></div></div><section class="panel">${events.length?events.map(e=>`<div class="history-row"><div class="task-icon">${esc(e.icon)}</div><div class="task-info"><h3>${esc(e.title)}</h3><p>${e.kind==='complete'?(e.submittedLate?'Saatinden sonra tamamlandı · ebeveyn onaylı':'Tamamlandı ve onaylandı'):e.kind==='expired'?'Süresi doldu · puan kazanılamadı':e.kind==='cancelled'?'İptal edildi · puan verilmedi':'Ödül alındı'} · ${new Intl.DateTimeFormat('tr-TR',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date(e.at))}</p>${e.goalTitle?`<p>Hedef: ${esc(e.goalTitle)}</p>`:''}</div><span class="points" style="color:${e.delta>0?'var(--green)':'var(--pink)'}">${e.delta>0?'+':''}${number(e.delta)} puan</span></div>`).join(''):'<div class="empty">Hikâyen burada başlıyor.<br>Hedefini seç, çarkı çevir, zamanında tamamla! 🌟</div>'}</section>`;}
function competitionCard(c){
 const labels={active:'Yarışma sürüyor',achieved:'Ortak ödül hazır! 🎉',claimed:'Ödül alındı',expired:'Süre sona erdi',cancelled:'Yarışma iptal edildi'},pct=Math.min(100,c.total/c.target*100);
 return `<article class="competition-card ${c.status}"><div class="competition-header"><span class="competition-icon">${esc(c.icon)}</span><div><div class="eyebrow">AİLECE BİRLİKTE</div><h2>${esc(c.title)}</h2><p>Ortak büyük ödül: <strong>${esc(c.prize)}</strong></p></div><span class="badge">${labels[c.status]}</span></div><div class="competition-progress"><strong>${number(c.total)} <small>/ ${number(c.target)} puan</small></strong><span>%${Math.floor(pct)}</span></div><div class="progress" role="progressbar" aria-label="Ortak ödül ilerlemesi" aria-valuemin="0" aria-valuemax="${c.target}" aria-valuenow="${Math.min(c.total,c.target)}"><span style="width:${pct}%"></span></div><div class="competition-meta"><span>${formatDeadline(c.startedAt)} → ${formatDeadline(c.endsAt)}</span>${c.status==='active'?`<span data-countdown="${c.endsAt}" data-competition-timer>${remaining(c.endsAt)}</span>`:`<span>${labels[c.status]}</span>`}</div><div class="competition-team">${c.leaderboard.map((u,i)=>`<button type="button" tabindex="-1"><span>${avatarMarkup(u)}</span><strong>${esc(u.name)}</strong><small>${c.leaderboard.findIndex(x=>x.points===u.points)+1}. sıra · ${u.completed} görev</small><b>+${number(u.points)}</b></button>`).join('')}</div><p class="competition-rule">Yarışma başladıktan sonra süresinde tamamlanan görevler sayılır. Ortak ödül, kişisel puan bakiyelerini azaltmaz.</p><div class="competition-actions">${c.status==='active'?'<button class="primary" data-nav="wheel">Çarktan görev al →</button>':''}${c.status==='achieved'?`<button class="primary" data-claim-competition="${c.id}">🎁 Ortak ödülü aldık</button>`:''}${['active','achieved'].includes(c.status)?`<button class="text-button" data-cancel-competition="${c.id}">Yarışmayı iptal et</button>`:''}</div></article>`;
}
