function personalPanel(){
 const u=user();if(u.memberType==='parent')return `${wishSummary()}${parentDailyPanel()}${parentAssignmentsPanel()}`;const active=state.assignments.filter(a=>a.userId===selected&&assignmentStatus(a)==='active').length,pending=state.assignments.filter(a=>a.userId===selected&&a.status==='pending').length;
 return `${u.memberType==='parent'?parentDailyPanel():''}${u.memberType==='child'?`<section class="daily-shortcut panel"><span aria-hidden="true">☀️</span><div><h2>Bugünün küçük adımları</h2><p>${(state.dailyRoutines||[]).filter(t=>t.status==='active').length} günlük görev seni bekliyor.</p></div><button class="primary" data-nav="daily">Günlük görevler →</button></section>`:''}<div class="stats-grid"><div class="panel stat"><strong>${number(u.balance)}</strong><span class="quiet">Kullanılabilir puan</span></div><div class="panel stat"><strong>${active}</strong><span class="quiet">Aktif görev</span></div><div class="panel stat"><strong>${pending}</strong><span class="quiet">Onay bekleyen</span></div></div>${u.memberType==='child'?`<section class="wish-shortcut"><div><strong>Bir hayalin mi var? 🎁</strong><p class="quiet">Ebeveyninden ödül iste, görevlerle hedefine yaklaş.</p></div><div class="goal-actions"><button class="primary" data-action="new-wish">${icon('gift')} Ödül iste</button><button class="text-button" data-nav="wishes">İsteklerim ve hedefim →</button></div></section>`:''}${wishSummary()}${assignmentsPanel()}`;
}

function competitionEditor(){
 openModal('Aile yarışması başlat 🏆',`<form id="competition-form"><label>Yarışmanın adı<input name="title" maxlength="80" placeholder="Örneğin: Birlikte başarma haftası" required></label><label>Ortak büyük ödül<input name="prize" maxlength="100" placeholder="Örneğin: Ailece lunapark gezisi" required></label><div class="form-grid"><label>Ailenin toplam puan hedefi<input name="target" type="number" min="1" max="100000" value="500" required></label><label>Ödül simgesi<input name="icon" maxlength="12" value="🏆" required></label></div><label>Şu andan itibaren süre<select name="frequency">${Object.entries(periods).map(([k,v])=>`<option value="${k}" ${k==='weekly'?'selected':''}>${v}</option>`).join('')}</select></label><p>Katılan üyelerin yarışma boyunca tamamladığı görevlerin puanı birleşir. Kişisel puanlarınız da korunur.</p><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-close>Vazgeç</button><button class="primary">Yarışmayı başlat</button></div></form>`);
 $('#competition-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.target=Number(data.target);commit('createCompetition',data,'Aile yarışması başladı. Birlikte başarabilirsiniz! 🏆');};
}
function confirmFamilyAction(action,id){
 const cancelTask=action==='cancelAssignment',claim=action==='claimCompetition';
 openModal(claim?'Ortak ödülünüz hazır! 🎉':cancelTask?'Görev iptal edilsin mi?':'Yarışma iptal edilsin mi?',`<p>${claim?'Ödül alındı olarak kaydedilecek; herkesin kişisel puanı korunacak.':cancelTask?'Bu görevden puan kazanılmaz. İptal kaydı geçmişinde kalır ve çarktan yeniden görev alabilirsin.':'Yarışma kapanacak. Tamamlanan görevlerin kişisel puanları ve yarışma geçmişi korunacak.'}</p><div class="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-close>Vazgeç</button><button class="${claim?'primary':'danger'}" id="family-confirm">${claim?'Ödülü aldık':'Evet, iptal et'}</button></div>`);
 $('#family-confirm').onclick=()=>commit(action,cancelTask?{userId:selected,assignmentId:id}:{id},claim?'Ortak ödülünüz kutlu olsun! 🎉':'İptal edildi. Geçmiş kaydı korundu.');
}
function readRoute(){const [route,id]=location.hash.slice(1).split('/');if(Object.hasOwn(names,route))page=route;}
readRoute();
window.addEventListener('hashchange',()=>{if(spinning||busy)return;readRoute();modal.close();render();});
function render(){
 if(!state)return;selected=state.viewerId;
 if(user().memberType==='young_child'){if(!['account','games'].includes(page))page='profile';history.replaceState(null,'',page==='profile'?'#profile/'+selected:'#'+page);root.innerHTML=kidScreen();if(page==='account')bindProfileSettings();if(page==='games'){wheelAngle=gameAngles.get(selected)||0;const games=gameCandidates();drawWheel(games,games.find(g=>g.title===gameResults.get(selected))?.id,true);}return;}
 if(['home','competitions','rewards'].includes(page))page='profile';
 if(user().memberType==='child'&&['approvals','progress','admin'].includes(page))page='profile';
 if(user().memberType==='parent'&&['wheel','daily','history'].includes(page))page='profile';
 if(['tasks','settings'].includes(page))page='admin';
 if(page==='admin'&&state.viewerRole!=='admin')page='profile';
 if(['pool','games'].includes(page)&&user().memberType!=='parent')page='profile';
 if(page==='progress'&&!state.canViewProgress)page='profile';
 if(page==='wishes'&&!['child','parent'].includes(user().memberType))page='profile';
 if(page==='daily'&&user().memberType!=='child')page='profile';
 history.replaceState(null,'',`#${page}${page==='profile'?'/'+selected:''}`);
 if(page==='wheel'){root.innerHTML=wheelExperience();wheelAngle=0;drawWheel();return;}
 const pending=state.assignments.filter(a=>a.reviewerId===selected&&a.status==='pending').length;
 const isParent=user().memberType==='parent';
 const nav=isParent?[['profile','Günlük görevler','tasks'],['pool','Görev havuzu','plus'],['games','Oyun çarkı','wheel'],['progress','Tamamlanma takibi','star'],['approvals',`Onay bekleyenler${pending?' · '+pending:''}`,'check'],['wishes','Ödül istekleri','gift'],['account','Profil ayarları','settings']]:[['profile','Sayfam','home'],['daily','Günlük görevler','tasks'],['wheel','Görev çarkı','wheel'],['account','Profil ayarları','settings']];
 if(state.viewerRole==='admin')nav.push(['admin','Yönetim','settings']);
 const titles={wishes:user().memberType==='child'?'Hayallerin burada başlıyor':'Çocukların hayalleri',daily:'Günlük görevlerin',progress:'Çocukların küçük adımları',account:'Profil ayarların',home:'Ailenin başarı panosu',profile:`Merhaba, ${esc(user().name)}.`,rewards:'Sıradaki hedefin',approvals:'Onay bekleyen görevler',admin:'Yönetim merkezi',history:'Görev geçmişim',competitions:'Aile yarışmaları'};
 const contents={games:gamesPanel,pool:parentTaskPool,wishes:rewardWishesPanel,daily:childDailyPanel,progress:progressPanel,account:profileSettings,home:()=>`${profileCards()}${familySummary()}<div class="dashboard-footer"><span>Toplam kazanılan puana göre sıralanır.</span><button class="secondary" data-nav="profile">Sayfama git ${icon('arrow')}</button></div>`,profile:personalPanel,rewards:()=>rewardsPanel(true),approvals:approvalsPanel,admin:adminPanel,history:historyPanel,competitions:()=>`${familySummary()}<button class="secondary" data-nav="profile">Aile panosuna dön</button>`};
 root.innerHTML=`<div class="layout calm-layout"><aside class="sidebar"><a href="#profile" class="brand" data-nav="profile"><span class="brand-icon">⌂</span><div>home<span>dojo</span></div></a><div class="workspace">BİZİM EVİMİZ</div><nav class="nav" aria-label="Ana menü">${nav.map(([key,title,glyph])=>`<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(glyph)}<span>${title}</span></button>`).join('')}</nav><div class="sidebar-bottom"><span class="tiny-dot"></span>${state.viewerRole==='admin'?'Admin':memberTypes[user().memberType]||'Aile üyesi'}<button data-action="logout" aria-label="Çıkış yap">${icon('logout')}</button></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">${names[page]}</span><div class="top-right"><button class="top-profile" data-nav="profile"><span class="mini-avatar">${avatarMarkup(user())}</span>${esc(user().name)}</button><button class="icon-button mobile-logout" data-action="logout" aria-label="Çıkış yap">${icon('logout')}</button></div></header><div class="content"><div class="heading"><div><div class="eyebrow">${page==='admin'?'YALNIZCA ADMİN':'HOMEDOJO'}</div><h1>${titles[page]||names[page]}</h1></div>${page==='profile'&&user().memberType==='child'?`<button class="primary" data-nav="wheel">${icon('wheel')} Görev al</button>`:''}</div>${(contents[page]||personalPanel)()}</div></main></div>`;if(page==='account')bindProfileSettings();if(page==='progress')loadProgress();
}
let progressMode='day',progressSource='daily',progressDate='',progressEnd='',progressChild='all',progressRequest=0,progressSignature='';
const shortDate=day=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short',timeZone:'Europe/Istanbul'}).format(new Date(day+'T12:00:00+03:00'));
const percent=value=>value===null?'—':'%'+number(value);
function childDailyPanel(){
 const tasks=state.dailyRoutines||[],done=tasks.filter(t=>t.status==='completed').length,pending=tasks.filter(t=>t.status==='pending').length;
 const groups=[['morning','☀️','Sabah',t=>t.time<'12:00'],['noon','🌤️','Öğlen',t=>t.time>='12:00'&&t.time<'18:00'],['evening','🌙','Akşam',t=>t.time>='18:00']];
 return `<div class="daily-intro"><div><span class="eyebrow">HER GÜN BİR KÜÇÜK ADIM</span><h2>Bugünün planı</h2><p>${shortDate(state.today)} · ${done} tamamlandı${pending?' · '+pending+' onay bekliyor':''}</p></div><span class="daily-intro-art" aria-hidden="true">🌱</span></div>${groups.map(([key,emoji,title,test])=>{const list=tasks.filter(test);return list.length?`<section class="daily-period"><div class="section-heading"><h2>${emoji} ${title}</h2><span class="quiet">${list.filter(t=>t.status==='completed').length} / ${list.length} tamamlandı</span></div><div class="daily-task-grid">${list.map(t=>`<article class="daily-card ${t.status}"><div class="daily-card-top"><span class="task-icon">${esc(t.icon)}</span><span>${t.time} – ${t.until}${t.status==='active'&&t.late?' · Saati geçti':''}</span></div><h3>${esc(t.title)}</h3><div class="daily-card-bottom"><span class="points">+${number(t.points)} puan</span>${t.status==='active'?`<button class="primary" data-complete-routine="${t.id}">${icon('check')} Yaptım</button>`:`<span class="daily-status">${({upcoming:'Saati gelince',pending:'Onay bekliyor',completed:'✓ Tamamlandı',expired:'Süresi doldu',cancelled:'İptal edildi'})[t.status]||''}</span>`}</div></article>`).join('')}</div></section>`:'';}).join('')||'<div class="panel empty">Günlük programın henüz hazırlanmamış.</div>'}<p class="daily-footnote">Planlanan saat geçse de gün boyunca tamamlayabilirsin. Saatler Türkiye saatine göredir. “Yaptım” dediğinde ${esc(state.guardianName)} onayı istenir; puanın onaydan sonra eklenir.</p>`;
}
function progressPanel(){
 progressDate ||= state.today;progressEnd ||= state.today;
 return `<section class="report-filters panel"><div class="report-period" role="group" aria-label="Rapor dönemi"><button data-progress-mode="day" class="${progressMode==='day'?'active':''}" aria-pressed="${progressMode==='day'}">Gün</button><button data-progress-mode="week" class="${progressMode==='week'?'active':''}" aria-pressed="${progressMode==='week'}">Hafta</button><button data-progress-mode="range" class="${progressMode==='range'?'active':''}" aria-pressed="${progressMode==='range'}">Tarih aralığı</button></div><label>${progressMode==='range'?'Başlangıç':progressMode==='day'?'Gün seç':'Haftadan bir gün seç'}<input type="date" id="progress-date" value="${progressDate}" min="2000-01-01" max="2100-12-31"></label>${progressMode==='range'?`<label>Bitiş<input type="date" id="progress-end" value="${progressEnd}" min="${progressDate}" max="2100-12-31"></label>`:''}<label>Çocuk<select id="progress-child"><option value="all">Tüm çocuklar</option>${state.users.filter(u=>['child','young_child'].includes(u.memberType)).map(u=>`<option value="${u.id}" ${progressChild===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><label>Görevler<select id="progress-source"><option value="daily" ${progressSource==='daily'?'selected':''}>Günlük program</option><option value="wheel" ${progressSource==='wheel'?'selected':''}>Çarktan alınanlar</option></select></label></section><div class="report-navigation" ${progressMode==='range'?'hidden':''}><button class="text-button" data-progress-step="-1">← Önceki ${progressMode==='day'?'gün':'hafta'}</button><button class="text-button" data-progress-today>Bugün</button><button class="text-button" data-progress-step="1">Sonraki ${progressMode==='day'?'gün':'hafta'} →</button></div><div id="progress-results" aria-live="polite"><div class="panel empty">Görevler hesaplanıyor…</div></div>`;
}
function progressResults(r){
 const daily=r.source==='daily',summary=r.summary;
 return `<div class="report-heading"><div><span class="eyebrow">${daily?'GÜNLÜK ALIŞKANLIKLAR':'ÇARKTAN ALINAN GÖREVLER'}</span><h2>${shortDate(r.start)}${r.end!==r.start?' – '+shortDate(r.end):''} <span>${r.start.slice(0,4)}</span></h2></div><span class="report-live"><i></i> Güncel takip</span></div><div class="report-metrics"><article class="panel report-main-stat"><span>Onaylı tamamlanma</span><strong>${percent(summary.rate)}</strong><div class="progress"><span style="width:${summary.rate||0}%"></span></div><small>${summary.completed} / ${summary.total} görev</small></article><article class="panel report-stat"><span class="metric-icon approved">${icon('check')}</span><strong>${summary.completed}</strong><span>Onaylandı</span></article><article class="panel report-stat"><span class="metric-icon waiting">${icon('history')}</span><strong>${summary.pending}</strong><span>Onay bekliyor</span></article><article class="panel report-stat"><span class="metric-icon continuing">${icon('tasks')}</span><strong>${summary.active}</strong><span>${daily?'Tamamlanabilir':'Süresi devam ediyor'}</span></article></div><p class="report-rule">${daily?'Oran = onaylanan / saati gelen günlük görev. Gelecek gün ve saatler hesaba katılmaz.':'Oran = onaylanan / seçili tarihlerde çarktan alınan görev. Sonradan gelen onaylar, görevin alındığı tarihe işlenir.'} Bekleyen onaylar henüz başarı sayılmaz. ${summary.expired||summary.cancelled?`Süresi dolan: ${summary.expired} · İptal: ${summary.cancelled}.`:''}</p>${r.mode==='week'?`<div class="report-week" aria-label="Haftanın günlük tamamlanma oranları">${r.days.map(d=>`<div class="report-day ${d.day>r.today?'future':''}"><span>${new Intl.DateTimeFormat('tr-TR',{weekday:'short',timeZone:'Europe/Istanbul'}).format(new Date(d.day+'T12:00:00+03:00'))}</span><div class="day-track"><i style="height:${d.rate||0}%"></i></div><strong>${percent(d.rate)}</strong><small>${d.completed}/${d.total}</small></div>`).join('')}</div>`:''}<div class="report-children">${r.rows.map((u,i)=>`<details class="panel child-report" data-report-child="${u.userId}" ${i===0?'open':''}><summary><span class="avatar">${avatarMarkup(u)}</span><div class="report-child-name"><strong>${esc(u.name)}${u.archived?' · Arşiv':''}</strong><span>${memberTypes[u.memberType]} · ${u.completed}/${u.total} onaylı görev</span></div><strong class="report-child-rate">${percent(u.rate)}</strong><span class="report-expand" aria-hidden="true">⌄</span></summary><div class="child-report-body">${daily&&u.trackingSince&&r.start<u.trackingSince?`<p class="tracking-note">Düzenli takip ${shortDate(u.trackingSince)} tarihinde başladı. Öncesinde yalnızca kayıtlı görevler gösterilir.</p>`:''}${u.tasks.length?`<div class="task-report-scroll"><table class="task-report-table"><thead><tr><th scope="col">Görev</th><th scope="col">Onaylı</th><th scope="col">Bekleyen</th><th scope="col">Devam</th><th scope="col">Eksik¹</th><th scope="col">Başarı</th></tr></thead><tbody>${u.tasks.map(t=>`<tr><th scope="row"><span>${esc(t.icon)}</span><div>${esc(t.title)}${t.time?`<small class="report-task-time">${esc(t.time)} · Günlük</small>`:''}${r.mode==='week'?`<div class="task-week-dots" aria-label="Görevin günlük durumu">${t.days.map(d=>`<span class="${d.total===0?'unplanned':d.completed===d.total?'done':d.pending?'pending':d.active?'active':'missed'}" title="${shortDate(d.day)}: ${d.total?d.completed+'/'+d.total+' onaylandı, '+d.pending+' bekliyor':'Planlanan görev yok veya henüz zamanı gelmedi'}" aria-label="${shortDate(d.day)}: ${d.total?d.completed+'/'+d.total+' onaylı':'Hesaplanmadı'}">${d.total===0?'·':d.completed===d.total?'✓':d.pending?'◷':d.active?'○':'–'}</span>`).join('')}</div>`:''}</div></th><td data-label="Onaylı">${t.completed}/${t.total}</td><td data-label="Bekleyen">${t.pending}</td><td data-label="Devam">${t.active}</td><td data-label="Eksik">${t.expired+t.cancelled}</td><td><div class="task-rate"><strong>${percent(t.rate)}</strong><div class="progress"><span style="width:${t.rate||0}%"></span></div></div></td></tr>`).join('')}</tbody></table></div><p class="report-table-note">¹ ${daily?'Önceki günlerde tamamlanmamış veya iptal edilmiş görevler.':'Süresi dolan veya iptal edilen görevler.'}${r.mode==='week'?' Günler soldan sağa Pazartesi–Pazar.':''}</p>`:'<p class="empty">Bu aralıkta hesaplanacak görev yok.</p>'}</div></details>`).join('')||'<div class="panel empty">Henüz çocuk profili yok. Admin panelinden ekleyebilirsin.</div>'}</div>`;
}
async function loadProgress(){
 const request=++progressRequest,viewer=selected;const container=$('#progress-results');if(!container||!state.canViewProgress)return;
 container.setAttribute('aria-busy','true');
 try{const result=await api('progress&'+new URLSearchParams({mode:progressMode,date:progressDate||state.today,endDate:progressEnd||state.today,source:progressSource,childId:progressChild}));if(request!==progressRequest||page!=='progress'||selected!==viewer||!container.isConnected)return;
 const signature=JSON.stringify({...result.report,serverNow:''});if(progressSignature===signature&&container.querySelector('.report-heading'))return;progressSignature=signature;
 const expanded=[...container.querySelectorAll('[data-report-child][open]')].map(el=>el.dataset.reportChild),hadRows=!!container.querySelector('[data-report-child]');
 container.innerHTML=progressResults(result.report);if(hadRows&&progressChild==='all')container.querySelectorAll('[data-report-child]').forEach(el=>el.open=expanded.includes(el.dataset.reportChild));
 const select=$('#progress-child');select.innerHTML='<option value="all">Tüm çocuklar</option>'+result.report.children.map(u=>`<option value="${u.id}">${esc(u.name)}${u.archived?' · Arşiv':''}</option>`).join('');select.value=progressChild;
 }catch(error){if(request===progressRequest&&container.isConnected)container.innerHTML=`<div class="panel empty">${esc(error.message)}<br><button class="secondary" data-progress-retry>Yeniden dene</button></div>`;}finally{if(request===progressRequest&&container.isConnected)container.removeAttribute('aria-busy');}
}
function moveProgress(step){const d=new Date((progressDate||state.today)+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+step*(progressMode==='week'?7:1));const next=d.toISOString().slice(0,10);if(next<'2000-01-01'||next>'2100-12-31')return;progressDate=next;render();}

function profileSettings(){
 const u=user();
 return `<div class="profile-settings"><section class="panel profile-settings-card"><h2>Profil fotoğrafı</h2><p>Aile panosunda ve profilinde görünecek.</p><form id="photo-form"><div class="photo-editor"><span class="large-avatar" id="photo-preview">${avatarMarkup(u)}</span><div><label class="secondary photo-file">Fotoğraf seç<input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Profil fotoğrafı seç"></label><p>JPG, PNG veya WebP · En fazla 8 MB</p></div></div><div class="form-error" role="alert"></div><div class="profile-form-actions"><button class="primary" id="photo-save" disabled>Fotoğrafı kaydet</button>${u.photo?'<button class="text-button" type="button" data-remove-photo>Fotoğrafı kaldır</button>':''}</div></form></section><section class="panel profile-settings-card"><h2>Giriş bilgileri</h2><p>Kullanıcı adını veya şifreni değiştirebilirsin.</p><form id="credentials-form"><label>Kullanıcı adı<input name="username" value="${esc(u.username)}" autocomplete="username" pattern="[a-zA-Z0-9._-]{3,32}" maxlength="32" required></label><label>Mevcut şifre<input type="password" name="currentPassword" autocomplete="current-password" required></label><details><summary>Şifremi de değiştir</summary><label>Yeni şifre<input name="password" type="password" minlength="4" maxlength="72" autocomplete="new-password"></label><label>Yeni şifre tekrar<input name="passwordConfirm" type="password" minlength="4" maxlength="72" autocomplete="new-password"></label><p>En az 4 karakter. Boş bırakırsan mevcut şifren korunur.</p></details><p class="account-session-note">Kaydettiğinde diğer cihazlardaki oturumların kapanır. Bu cihazda açık kalırsın.</p><div class="form-error" role="alert"></div><button class="primary">Giriş bilgilerini kaydet</button></form></section></div>`;
}
function bindProfileSettings(){
 let photo='';const form=$('#photo-form'),error=form.querySelector('.form-error'),save=$('#photo-save');
 $('#photo-file').onchange=async e=>{
  photo='';save.disabled=true;error.textContent='';const file=e.target.files[0];if(!file)return;
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){error.textContent='8 MB altında bir JPG, PNG veya WebP fotoğraf seç.';return;}
  const url=URL.createObjectURL(file);
  try{const img=new Image();img.src=url;await img.decode();if(img.naturalWidth*img.naturalHeight>40000000)throw new Error('Fotoğraf çok büyük. Daha küçük bir fotoğraf seç.');const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d');ctx.fillStyle='#f5f2fc';ctx.fillRect(0,0,256,256);const side=Math.min(img.naturalWidth,img.naturalHeight);ctx.drawImage(img,(img.naturalWidth-side)/2,(img.naturalHeight-side)/2,side,side,0,0,256,256);photo=canvas.toDataURL('image/jpeg',.88);$('#photo-preview').innerHTML=avatarMarkup({photo});save.disabled=false;}catch(err){error.textContent=err.message||'Fotoğraf okunamadı.';}finally{URL.revokeObjectURL(url);}
 };
 form.onsubmit=async e=>{e.preventDefault();if(!photo||busy)return;busy=true;save.disabled=true;try{const result=await api('savePhoto',{photo});acceptState(result.state);render();toast('Profil fotoğrafın güncellendi.');}catch(err){error.textContent=err.message;}finally{busy=false;if(save.isConnected)save.disabled=false;}};
 const credentials=$('#credentials-form');credentials.onsubmit=async e=>{e.preventDefault();if(busy)return;const data=Object.fromEntries(new FormData(credentials)),error=credentials.querySelector('.form-error'),button=credentials.querySelector('button');error.textContent='';if(data.password!==data.passwordConfirm){error.textContent='Yeni şifreler eşleşmiyor.';return;}busy=true;button.disabled=true;try{const result=await api('changeCredentials',data);csrf=result.csrf;acceptState(result.state);render();toast('Giriş bilgilerin güncellendi. Diğer oturumların kapatıldı.');}catch(err){error.textContent=err.message;}finally{busy=false;button.disabled=false;}};
}
function familySummary(){
 const c=state.familyGoal;
 if(!c)return `<section class="panel family-summary"><span class="family-prize">🏆</span><div><h2>Birlikte kazanacağınız bir ödül</h2><p>${state.viewerRole==='admin'?'Admin panelinden ortak ödüllü bir yarışma başlat.':'Yeni aile yarışması başladığında burada görünecek.'}</p></div>${state.viewerRole==='admin'?'<button class="secondary" data-nav="admin">Yönet</button>':''}</section>`;
 const pct=Math.min(100,c.total/c.target*100);
 return `<section class="panel family-summary"><span class="family-prize">${esc(c.icon)}</span><div class="family-summary-copy"><div class="eyebrow">ORTAK ÖDÜL</div><h2>${esc(c.prize)}</h2><div class="progress" role="progressbar" aria-label="Ortak hedef" aria-valuemin="0" aria-valuemax="${c.target}" aria-valuenow="${Math.min(c.total,c.target)}"><span style="width:${pct}%"></span></div><p>${number(c.total)} / ${number(c.target)} puan · ${c.status==='achieved'?'Hedef tamamlandı!':formatDeadline(c.endsAt)+' tarihine kadar'}</p></div><button class="secondary" data-nav="wheel">Katkıda bulun</button></section>`;
}
function approvalsPanel(){
 const items=state.assignments.filter(a=>a.reviewerId===selected&&a.status==='pending');
 return `<div class="assignment-grid">${items.map(a=>{const owner=state.users.find(u=>u.id===a.userId);return `<article class="assignment-card"><div class="assignment-top"><span class="task-icon">${esc(a.icon)}</span><span class="badge">${esc(owner.name)}</span><strong>+${number(a.points)}</strong></div><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><p>${formatDeadline(a.submittedAt)} · Tamamlandı olarak gönderildi</p>${a.routineId?`<p class="routine-timing">Planlanan saat: ${esc(a.routineTime||'')} – ${new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Istanbul'}).format(new Date(a.dueAt))} · ${a.submittedLate?'Saatinden sonra gönderildi; onaylayabilirsiniz.':'Planlanan saat aralığında gönderildi.'}</p>`:''}<div class="review-actions"><button class="primary" data-review="${a.id}" data-decision="approve">${icon('check')} Onayla</button><button class="secondary" data-review="${a.id}" data-decision="reject">Geri gönder</button></div></article>`;}).join('')||'<div class="panel empty">Tüm işler tamam. Onayını bekleyen görev yok. ✨</div>'}</div>`;
}
function adminPanel(){
 if(['competitions','rewards'].includes(adminTab))adminTab='tasks';
 if(adminTab!=='tasks'&&adminPerson==='shared')adminPerson=selected;
 return `<div class="section-heading"><h2>Yönetim</h2><button class="secondary" data-nav="games">Oyun çarkını yönet →</button></div><div class="admin-tabs" role="group" aria-label="Yönetim bölümleri">${[['tasks','Görevler'],['users','Kullanıcılar']].map(([key,label])=>`<button class="${adminTab===key?'active':''}" data-admin-tab="${key}">${label}<span>${key==='tasks'?state.tasks.filter(adminTaskVisible).length:key==='rewards'?state.rewards.filter(r=>r.ownerId===(adminPerson==='shared'?selected:adminPerson)).length:key==='users'?state.users.length:state.competitions.length}</span></button>`).join('')}</div><section class="admin-workspace">${['tasks','rewards'].includes(adminTab)?adminPersonPicker():''}${adminTab==='tasks'&&state.users.find(u=>u.id===adminPerson)?.memberType==='child'?`<div class="daily-admin-link"><span>Bu çocuğun saatli günlük görevleri de var.</span><button class="secondary" data-routines="${adminPerson}">Günlük program</button></div>`:''}${adminTab==='tasks'&&state.users.find(u=>u.id===adminPerson)?.memberType==='young_child'?`<section class="notice">Bu kullanıcı günlük mektup ekranını kullanır. <button class="secondary" data-routines="${adminPerson}">Günlük programı düzenle</button></section>`:adminTab==='tasks'?tasksPanel():adminTab==='rewards'?adminRewards():adminTab==='competitions'?competitionsPanel(true):usersPanel()}</section>`;
}
function adminPersonPicker(){return `<div class="admin-person-picker"><label>Kimin ${adminTab==='tasks'?'görevleri':'ödülleri'}?<select id="admin-person">${adminTab==='tasks'?`<option value="shared" ${adminPerson==='shared'?'selected':''}>👥 Ortak görevler</option>`:''}${state.users.map(u=>`<option value="${u.id}" ${u.id===adminPerson?'selected':''}>${esc(u.avatar)} ${esc(u.name)}</option>`).join('')}</select></label><p>${adminTab==='tasks'?'Ortak görevler seçilen kişilerin çarklarında görünür. Herkes ayrı tamamlar ve puan kazanır.':'Buradaki değişiklikler yalnızca seçilen kişinin listesine uygulanır.'}</p></div>`;}
function adminRewards(){return `<div class="section-heading"><h2>Ödüller</h2><button class="primary" data-action="new-reward">${icon('plus')} Ödül ekle</button></div><section class="panel">${state.rewards.filter(r=>r.ownerId===adminPerson).map(r=>`<div class="task-row"><span class="task-icon">${esc(r.icon)}</span><div class="task-info"><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p></div><strong class="points">${number(r.cost)} puan</strong><button class="icon-button" data-edit-reward="${r.id}" aria-label="${esc(r.title)} düzenle">${icon('edit')}</button><button class="icon-button" data-delete-reward="${r.id}" aria-label="${esc(r.title)} sil">${icon('trash')}</button></div>`).join('')||'<div class="empty">Henüz ödül yok.</div>'}</section>`;}
const memberTypes={parent:'Ebeveyn',child:'Büyük çocuk',young_child:'Küçük çocuk'};
const openedLetters=new Set();
function kidAssignedTasks(){
 const rows=state.assignments.filter(a=>a.userId===selected&&!a.routineId&&['active','pending'].includes(assignmentStatus(a)));
 return rows.length?`<section class="kid-extra-tasks"><h2>Sana özel görevler ✨</h2>${rows.map(a=>`<article><span>${esc(a.icon)}</span><div><h3>${esc(a.title)}</h3><p>${esc(a.description||'Yaptığında ebeveynin onaylayacak.')}</p></div><strong>+${number(a.points)} ⭐</strong></article>`).join('')}</section>`:'';
}
const gameResults=new Map(),gameAngles=new Map();
function gameCandidates(){return (state.gameNames||[]).map((title,i)=>({id:String(i),title,icon:['🙈','🧩','🎨','🎲','🎵','🐾'][i%6]}));}
function gamesPanel(){
 const children=state.gameChildren||[];
 return `<div class="section-heading"><div><h2>Küçüklerin oyun çarkı</h2><p>Her çocuk için oyunları yaz, çarkına renk kat.</p></div></div><div class="settings-grid">${children.map(c=>`<article class="panel game-settings"><h3>${esc(c.avatar)} ${esc(c.name)}</h3><div class="game-tags">${c.names.map(n=>`<span>${esc(n)}</span>`).join('')||'<p>Henüz oyun yok.</p>'}</div><button class="primary" data-edit-games="${c.id}">${icon('edit')} Oyunları düzenle</button></article>`).join('')||'<div class="panel empty">Küçük çocuk profili eklendiğinde oyunlarını burada düzenleyebilirsin.</div>'}</div>`;
}
function gamesEditor(id){
 const child=state.gameChildren.find(c=>c.id===id);if(!child)return;
 openModal(`${esc(child.name)} · Oyunlar`,`<form id="games-form"><label>Oyun isimleri<textarea name="games" rows="10" maxlength="600" placeholder="Saklambaç&#10;Lego zamanı&#10;Resim yap">${esc(child.names.join('\n'))}</textarea></label><p class="field-hint">Her satıra bir oyun yaz. İsimleri değiştirebilir, yeni satır ekleyebilir veya silebilirsin. En fazla 12 oyun, her isim en fazla 40 karakter.</p><div class="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" type="button" data-close>Vazgeç</button><button class="primary">Kaydet</button></div></form>`);
 $('#games-form').onsubmit=e=>{e.preventDefault();const names=new FormData(e.target).get('games').split('\n').map(n=>n.trim()).filter(Boolean);commit('saveGames',{childId:id,names},'Oyun çarkı güncellendi.');};
}
function kidGameWheel(){
 const games=gameCandidates(),last=gameResults.get(selected);
 return `<section class="kid-game-stage"><button class="kid-play-link" data-nav="profile">← Görevlerime dön</button><div class="wheel-panel kid-game-panel"><div class="wheel-head"><span class="kid-kicker">OYUN ZAMANI</span><h1>Ne oynayalım? 🎈</h1><p>Çevir, sürpriz oyununu keşfet!</p></div><div class="wheel-wrap"><div class="wheel-aura" aria-hidden="true"></div><div class="wheel-rim"></div><div class="wheel-lights" aria-hidden="true">${Array.from({length:48},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="wheel" id="wheel"><canvas id="wheel-canvas" width="1200" height="1200" aria-label="Oyun isimlerini gösteren çark"></canvas></div><div class="wheel-center" aria-hidden="true"><span>🎈</span></div><div class="pointer" aria-hidden="true"></div></div><div class="wheel-controls"><button class="wheel-sound" data-action="toggle-sound" aria-label="Çark sesi" aria-pressed="${wheelSound.enabled}">${soundButton()}</button><div class="game-result" id="game-result" role="status">${!games.length?'Ebeveynin çarkına oyun ekleyecek.':last&&games.some(g=>g.title===last)?`🎉 ${esc(last)} oynayalım!`:'Sürpriz oyun seni bekliyor!'}</div><button class="primary spin-button" data-action="spin-game" ${games.length?'':'disabled'}>🎡 Çarkı çevir</button></div><details class="wheel-legend"><summary>Oyunlarımız · ${games.length}</summary><ol>${games.map(g=>`<li>${esc(g.title)}</li>`).join('')}</ol></details></div></section>`;
}
async function spinGame(){
 const games=gameCandidates();if(spinning||busy||!games.length)return;
 spinning=true;wheelSound.unlock();const button=$('[data-action="spin-game"]'),panel=$('.kid-game-panel'),disc=$('#wheel');button.disabled=true;panel.setAttribute('aria-busy','true');panel.classList.add('is-spinning');
 try{
  const random=crypto.getRandomValues(new Uint32Array(1))[0]/4294967296,index=Math.floor(random*games.length),chosen=games[index],step=360/games.length,target=(360-(index+.5)*step)%360,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  $('#game-result').textContent='Oyunlar dönüyor…';if(!reduced)wheelSound.follow(disc,games.length);
  wheelAngle+=360*7+(target-wheelAngle%360+360)%360;void disc.offsetWidth;disc.style.transition=reduced?'none':'';disc.style.transform=`rotate(${wheelAngle}deg)`;
  await new Promise(r=>setTimeout(r,reduced?50:5900));
  gameResults.set(selected,chosen.title);gameAngles.set(selected,wheelAngle);wheelSound.finish();drawWheel(games,chosen.id,true);$('#game-result').textContent=`🎉 ${chosen.title} oynayalım!`;panel.classList.add('is-revealed');celebrate();
 }catch(e){wheelSound.stop();toast('Oyun çarkını yeniden çevirmeyi dene.');}finally{spinning=false;button.disabled=false;panel.classList.remove('is-spinning');panel.setAttribute('aria-busy','false');}
}
function kidScreen(){
 const tasks=state.dailyRoutines||[],current=tasks.find(t=>t.status==='active'),next=tasks.find(t=>t.status==='upcoming'),done=tasks.filter(t=>t.status==='completed').length,pending=tasks.filter(t=>t.status==='pending').length;
 const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Istanbul',hour:'2-digit',hourCycle:'h23'}).format(new Date(serverTime()))),phase=hour<12?'morning':hour<18?'noon':'evening',greeting=hour<12?'Günaydın':hour<18?'Merhaba':'İyi akşamlar',key=current?`${selected}:${state.today}:${current.id}`:'';
 return `<main class="kid-world ${phase}"><div class="kid-sky" aria-hidden="true"><span class="kid-sun">${phase==='evening'?'☾':'☀'}</span><span class="kid-cloud cloud-one">☁</span><span class="kid-cloud cloud-two">☁</span><span class="sky-star">✦</span></div><header class="kid-header"><a href="#profile" data-nav="profile" class="kid-brand">⌂ <span>homedojo</span></a><div><button class="kid-profile" data-nav="account" aria-label="Profil ayarlarım"><span class="mini-avatar">${avatarMarkup(user())}</span></button><button class="kid-exit" data-action="logout" aria-label="Çıkış yap">${icon('logout')}</button></div></header>${page==='games'?kidGameWheel():page==='account'?`<section class="kid-settings"><button class="secondary" data-nav="profile">← Görevlerime dön</button><h1>Profilim</h1>${profileSettings()}</section>`:`<section class="kid-adventure"><button class="kid-play-link" data-nav="games">🎡 Oyun çarkım <span>→</span></button><div class="kid-greeting"><span class="kid-kicker">BUGÜNÜN KÜÇÜK MACERASI</span><h1>${greeting}, ${esc(user().name)}!</h1><p>${current?'Sana bir görev mektubu geldi.':next?'Biraz dinlen, yeni mektubun yolda.':'Bugünün küçük adımları burada tamamlandı.'}</p></div><div class="kid-progress" aria-label="${done} görev onaylandı, ${pending} görev onay bekliyor">${tasks.map(t=>`<span class="${t.status}" title="${esc(t.title)} · ${t.status==='completed'?'Tamamlandı':t.status==='pending'?'Onay bekliyor':t.time}" aria-hidden="true">${t.status==='completed'?'★':t.status==='pending'?'♡':'·'}</span>`).join('')}</div>${current?`<div class="letter-stage ${openedLetters.has(key)?'open-static':''}" data-letter="${esc(key)}"><div class="letter-spark spark-one" aria-hidden="true">✦</div><div class="letter-spark spark-two" aria-hidden="true">✧</div><div class="envelope-shadow"></div><div class="envelope-back"></div><div class="envelope-flap"></div><article class="kid-task-card" style="--card-color:${['#ffdeb0','#d4c9ff','#c1ecd9','#ffcede'][tasks.indexOf(current)%4]}" aria-hidden="${!openedLetters.has(key)}"><div class="kid-card-top"><span>BUGÜNKÜ GÖREVİN</span><span>${esc(current.time)}</span></div><span class="kid-task-art" aria-hidden="true">${esc(current.icon)}</span><h2>${esc(current.title)}</h2><p>Küçük bir adım, kocaman bir aferin!</p><button class="kid-done" data-complete-routine="${current.id}" ${openedLetters.has(key)?'':'tabindex="-1"'}>${icon('check')} Yaptım!</button></article><div class="envelope-front"><span aria-hidden="true">💌</span><strong>${esc(user().name)} için</strong></div><button class="letter-open" data-open-letter="${esc(key)}" ${openedLetters.has(key)?'hidden':''} aria-label="Görev mektubunu aç"><span>✦</span> Mektubumu aç</button></div>`:`<div class="kid-rest"><span aria-hidden="true">${next?'🌈':'🌙'}</span><h2>${next?`${esc(next.time)}’te yeni bir mektup!`:'Bugünlük bu kadar!'}</h2><p>${next?'O zamana kadar güzel vakit geçir.':'Yarın yepyeni bir gün bizi bekliyor.'}</p></div>`}<p class="kid-approval-note" role="status">${pending?`♡ ${pending} görevin için ${esc(state.guardianName)} onayı bekleniyor.`:done?'⭐ Harikasın! Bugün '+done+' küçük adım tamamladın.':'Her gün küçük bir adım birlikte daha güzel.'}</p>${kidAssignedTasks()}<details class="kid-day-plan"><summary>Bugünün yolculuğu <span>⌄</span></summary><ol>${tasks.map(t=>`<li class="${t.status}"><span class="plan-icon">${esc(t.icon)}</span><span>${esc(t.title)}<small>${t.time} – ${t.until}</small></span><span>${t.status==='completed'?'⭐':t.status==='pending'?'♡':t.status==='expired'?'Yarın yeniden':t.status==='upcoming'?'Birazdan':'Şimdi'}</span></li>`).join('')||'<li>Ebeveynin günlük programını hazırlıyor.</li>'}</ol><p>Saatler Türkiye saatine göredir.</p></details></section>`}</main>`;
}
function openLetter(key){
 const stage=$('[data-letter]');if(!stage||stage.dataset.letter!==key)return;openedLetters.add(key);stage.classList.add('opening');stage.querySelector('.letter-open').hidden=true;stage.querySelector('.kid-task-card').setAttribute('aria-hidden','false');const b=stage.querySelector('.kid-done');b.removeAttribute('tabindex');setTimeout(()=>{if(b.isConnected)b.focus({preventScroll:true});},matchMedia('(prefers-reduced-motion: reduce)').matches?0:1100);
}
function usersPanel(){return `<div class="section-heading"><div><h2>Aile üyeleri</h2><p>Kullanıcı türünü ve kişisel programını buradan yönet.</p></div><button class="primary" data-action="new-account">${icon('plus')} Kullanıcı ekle</button></div><div class="settings-grid">${state.users.map(u=>`<article class="panel member-card"><div class="setting-user"><span class="avatar">${avatarMarkup(u)}</span><div class="task-info"><h3>${esc(u.name)}</h3><p>@${esc(u.username)} · ${memberTypes[u.memberType]||'Çocuk'}${u.role==='admin'?' · Admin':''}</p></div></div><div class="member-actions"><button class="secondary" data-edit-account="${u.id}">Düzenle</button>${['child','young_child'].includes(u.memberType)?`<button class="secondary" data-routines="${u.id}">Günlük program</button>`:''}${u.role!=='admin'?`<button class="text-button" data-archive-account="${u.id}">Çıkar</button>`:''}</div></article>`).join('')}</div>${state.archivedUsers?.length?`<details class="panel admin-help"><summary>Çıkarılan kullanıcılar · ${state.archivedUsers.length}</summary>${state.archivedUsers.map(u=>`<div class="task-row"><span>${esc(u.avatar)}</span><div class="task-info"><h3>${esc(u.name)}</h3><p>@${esc(u.username)}</p></div><button class="secondary" data-restore-account="${u.id}">Geri ekle</button></div>`).join('')}</details>`:''}`;}
function accountEditor(id){
 const u=state.users.find(x=>x.id===id)||{name:'',avatar:'🌟',username:'',memberType:'child'};
 openModal(id?'Hesap ayarları':'Yeni aile üyesi',`<form id="account-form"><div class="form-grid"><label>İsim<input name="name" value="${esc(u.name)}" maxlength="30" required></label><label>Simge<input name="avatar" value="${esc(u.avatar)}" maxlength="12" required></label></div><label>Kullanıcı türü<select name="memberType">${Object.entries(memberTypes).map(([key,label])=>`<option value="${key}" ${u.memberType===key?'selected':''} ${u.role==='admin'&&key!=='parent'?'disabled':''}>${label}</option>`).join('')}</select></label><div id="young-child-options" ${['child','young_child'].includes(u.memberType)?'':'hidden'}><p class="field-hint">Her iki çocuk türünde günlük program bulunur. Küçük çocuk yalnızca mektuplarını görür; çocuk hesabında çark ve ödüller de bulunur.</p><label>Görevleri onaylayacak ebeveyn<select name="guardianId">${state.users.filter(p=>p.memberType==='parent'&&p.id!==id).map(p=>`<option value="${p.id}" ${p.id===(u.guardianId||state.users.find(x=>x.role==='admin')?.id)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><label>Kullanıcı adı<input name="username" autocomplete="off" pattern="[a-zA-Z0-9._-]{3,32}" value="${esc(u.username)}" required></label>${id?'<details><summary>Şifreyi yenile</summary>':''}<label>${id?'Yeni şifre':'Şifre'}<input name="password" type="password" minlength="4" maxlength="72" autocomplete="new-password" ${id?'':'required'}></label><p class="field-hint">${id?'Boş bırakırsan mevcut şifre korunur. Yeni şifre tüm açık oturumları kapatır.':'En az 4 karakter. Yeni üye bu bilgilerle kendi hesabına girer.'}</p>${id?'</details>':''}<div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-close>Vazgeç</button><button class="primary">${id?'Kaydet':'Kullanıcı ekle'}</button></div></form>`);
 $('#account-form select[name="memberType"]').onchange=e=>{$('#young-child-options').hidden=!['child','young_child'].includes(e.target.value);};
 $('#account-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(id)data.id=id;commit(id?'saveAccount':'createAccount',data,id?'Hesap güncellendi.':'Yeni kullanıcı eklendi.');};
}
function archiveAccount(id){const u=state.users.find(u=>u.id===id);openModal('Aileden çıkarılsın mı?',`<p><strong>${esc(u.name)}</strong> giriş yapamayacak ve aile panosundan kalkacak. Eski puanları ve geçmişi korunur; istediğinde geri ekleyebilirsin. Açık görevleri iptal edilir. Bekleyen onayları uygun bir aile üyesine aktarılır.</p><div class="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-close>Vazgeç</button><button class="danger" id="archive-account">Kullanıcıyı çıkar</button></div>`);$('#archive-account').onclick=()=>commit('archiveAccount',{id},'Kullanıcı çıkarıldı. Geçmişi korundu.');}
function routineRow(r={id:crypto.randomUUID(),title:'',icon:'✨',time:'09:00',until:'12:00',points:10}){return `<fieldset class="routine-edit-row" data-routine-id="${r.id}"><legend>Günlük görev</legend><div class="routine-name"><label>Görev<input name="title" value="${esc(r.title)}" maxlength="80" required></label><label>Simge<input name="icon" value="${esc(r.icon)}" maxlength="12" required></label></div><div class="routine-times"><label>Başlangıç<input name="time" type="time" value="${r.time}" required></label><label>Bitiş<input name="until" type="time" value="${r.until}" required></label><label>Puan<input name="points" type="number" min="1" max="100000" value="${r.points}" required></label></div><button type="button" class="text-button" data-remove-routine>Görevi kaldır</button></fieldset>`;}
function routinesEditor(id){const u=state.users.find(u=>u.id===id);openModal(`${esc(u.name)} · Günlük program`,`<form id="routines-form"><p>Her gün tekrar eder. Kart başlangıç saatinde açılır; bitişten sonra onaya gönderilemez. Türkiye saati kullanılır. Geçmiş günlerin programı korunur; değişiklikler bugünden itibaren geçerlidir. Gönderilmiş görevlerin puanı ve süresi korunur.</p><div id="routine-rows">${(u.routineSchedule||[]).map(routineRow).join('')}</div><button type="button" class="secondary" id="add-routine">${icon('plus')} Günlük görev ekle</button><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-close>Vazgeç</button><button class="primary">Programı kaydet</button></div></form>`);
 $('#add-routine').onclick=()=>{if($('#routine-rows').children.length>=20){$('#routines-form .form-error').textContent='En fazla 20 günlük görev ekleyebilirsin.';return;}$('#routine-rows').insertAdjacentHTML('beforeend',routineRow());};
 $('#routine-rows').onclick=e=>{if(e.target.closest('[data-remove-routine]'))e.target.closest('fieldset').remove();};
 $('#routines-form').onsubmit=e=>{e.preventDefault();const routines=[...$('#routine-rows').children].map(row=>{const data={id:row.dataset.routineId};row.querySelectorAll('input').forEach(el=>data[el.name]=el.name==='points'?Number(el.value):el.value);return data;});commit('saveRoutines',{id,routines},'Günlük program kaydedildi.');};
}
function submitForReview(id){
 openModal('Kim onaylasın?',`<form id="review-request"><p>Görev puanın, seçtiğin kişi onayladığında eklenecek.</p><label>Onay verecek ebeveyn<select name="reviewerId" required><option value="">Bir kişi seç</option>${state.users.filter(u=>u.id!==selected&&u.memberType==='parent').map(u=>`<option value="${u.id}">${esc(u.avatar)} ${esc(u.name)}</option>`).join('')}</select></label><div class="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" type="button" data-close>Vazgeç</button><button class="primary">Onaya gönder</button></div></form>`);
 $('#review-request').onsubmit=e=>{e.preventDefault();commit('complete',{assignmentId:id,reviewerId:new FormData(e.target).get('reviewerId')},'Görevin onaya gönderildi.');};
}

function openModal(title,content){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="Kapat">${icon('close')}</button></div><div class="modal-body">${content}</div>`;modal.showModal();}
function editor(kind,id){const isTask=kind==='task',isUser=kind==='user';const value=(isTask?state.tasks:isUser?state.users:state.rewards).find(x=>x.id===id)||{};let fields;
 if(isUser){fields=`<label>İsim<input name="name" value="${esc(value.name)}" maxlength="30" required></label><label>Profil simgesi<input name="avatar" value="${esc(value.avatar)}" maxlength="12" required></label>`;}
 else{fields=`<label>${isTask?'Görev kime ait?':'Kime ait?'}<select name="ownerId" required>${isTask?`<option value="shared" ${value.scope==='shared'||(!id&&adminPerson==='shared')?'selected':''}>👥 Ortak görev</option>`:''}${state.users.map(u=>`<option value="${u.id}" ${u.id===(value.ownerId||adminPerson)&&value.scope!=='shared'?'selected':''}>${esc(u.avatar)} ${esc(u.name)}</option>`).join('')}</select></label>${isTask?`<fieldset id="task-participants" class="task-participants" ${value.scope==='shared'||(!id&&adminPerson==='shared')?'':'hidden'}><legend>Kimler yapabilir?</legend>${state.users.map(u=>`<label><input type="checkbox" name="participantIds" value="${u.id}" ${!value.participantIds||value.participantIds.includes(u.id)?'checked':''}>${esc(u.avatar)} ${esc(u.name)}</label>`).join('')}<p>En az iki kişi seç. Her kişinin görevi ve puanı ayrı takip edilir.</p></fieldset>`:''}<label>${isTask?'Görev':'Ödül'} adı<input name="title" value="${esc(value.title||'')}" maxlength="80" placeholder="${isTask?'Örneğin: Sofrayı hazırla':'Örneğin: Piknik günü'}" required></label><label>Açıklama<textarea name="description" maxlength="240" placeholder="Biraz ilham ekle…">${esc(value.description||'')}</textarea></label><div class="form-grid"><label>${isTask?'Kazanılacak puan':'Gerekli puan'}<input type="number" name="${isTask?'points':'cost'}" min="1" max="100000" step="1" value="${value.points||value.cost||(isTask?25:100)}" required></label><label>Simge<input name="icon" value="${esc(value.icon||(isTask?'✨':'🎁'))}" maxlength="12" required></label></div>${isTask?`<label>Atandığı andan itibaren süre<select name="frequency">${Object.entries(periods).map(([k,v])=>`<option value="${k}" ${(value.frequency||'daily')===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}`;}
 openModal(isUser?'Profilini düzenle':`${id?'Düzenle':'Yeni '+(isTask?'görev':'ödül')}`,`<form id="editor-form">${fields}<div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-close>Vazgeç</button><button class="primary" type="submit">${icon('check')} Kaydet</button></div></form>`);
 if(isTask)$('#editor-form select[name="ownerId"]').onchange=e=>{$('#task-participants').hidden=e.target.value!=='shared';};
 $('#editor-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(id)data.id=id;if(isTask){data.scope=data.ownerId==='shared'?'shared':'personal';data.participantIds=data.scope==='shared'?new FormData(e.target).getAll('participantIds'):[];}if(!isUser)adminPerson=data.ownerId;if(!isUser)data[isTask?'points':'cost']=Number(data[isTask?'points':'cost']);await commit(isUser?'saveUser':isTask?'saveTask':'saveReward',data,'Kaydedildi. Küçük bir adım daha!');};
}
async function commit(action,data,message){if(busy||spinning)return;wheelSound.unlock();busy=true;const buttons=[...modal.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{const result=await api(action,data);acceptState(result.state);render();modal.close();toast(message);if(action==='requestReward')wishEffect('Hayalin yola çıktı!','Ebeveynin puanını belirleyince başlayabilirsin.','💌');if(action==='reviewRewardRequest'&&data.decision==='approve')wishEffect('Yeni bir hedef doğdu!',`${number(data.cost)} puanlık bir macera başlıyor.`);if(action==='redeem')wishEffect('Başardın, bu ödül senin!','Küçük adımların kocaman bir başarıya dönüştü.','🏆');if(['parentApproveRoutine','reviewAssignment','redeem','claimCompetition'].includes(action))celebrate();}catch(e){const error=modal.querySelector('.form-error');if(modal.open&&error)error.textContent=e.message;else toast(e.message);await reloadState(false);}finally{busy=false;buttons.forEach(b=>b.disabled=false);}}
function confirmDelete(kind,id){const value=(kind==='task'?state.tasks:state.rewards).find(x=>x.id===id);openModal('Listeden kaldırılsın mı?',`<p><strong>${esc(value.title)}</strong> ${value.scope==='shared'?'seçilen herkesin çarkından':''} kaldırılacak. Önceki puanlar ve işlem geçmişi korunur.</p><div class="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-close>Vazgeç</button><button class="danger" id="confirm-delete">Evet, kaldır</button></div>`);$('#confirm-delete').onclick=()=>commit(kind==='task'?'deleteTask':'deleteReward',{id},'Listeden kaldırıldı.');}
function confirmReward(id){const r=state.rewards.find(x=>x.id===id);const requestId=crypto.randomUUID();openModal('Bu ödül senin olsun! 🎉',`<p><strong>${esc(r.title)}</strong> için ${number(r.cost)} puan kullanacaksın. Kalan puanın: <strong>${number(user().balance-r.cost)}</strong>.</p><div class="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-close>Biraz daha biriktir</button><button class="primary" id="confirm-redeem">${icon('gift')} Ödülü al</button></div>`);$('#confirm-redeem').onclick=()=>commit('redeem',{userId:selected,rewardId:id,requestId},`${r.title} senin! Güle güle kullan. 🎁`);}
async function spinWheel(){
 if(spinning||busy)return;
 wheelSound.unlock();
 if(page!=='wheel'){page='wheel';render();window.scrollTo({top:0,behavior:'instant'});}
 spinning=true;const button=$('[data-action="spin"]'),panel=$('.wheel-panel');
 button.disabled=true;button.innerHTML=`${icon('spark')} <span>Görevin seçiliyor…</span>`;
 panel.setAttribute('aria-busy','true');panel.querySelectorAll('[data-wheel-filter]').forEach(b=>b.disabled=true);
 try{
  const result=await api('spin',{userId:selected,frequency:'all',requestId:crypto.randomUUID()});acceptState(result.state);drawWheel(result.candidates);
  const index=result.candidates.findIndex(t=>t.id===result.task.id),step=360/result.candidates.length,target=(360-(index+.5)*step)%360;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  panel.classList.add('is-spinning');$('#wheel-result').textContent='Şansın dönüyor… Sıradaki başarıya hazır mısın?';button.innerHTML=`${icon('wheel')} <span>Şansın dönüyor…</span>`;
  if(!reduced)wheelSound.follow($('#wheel'),result.candidates.length);
  wheelAngle+=360*7+(target-wheelAngle%360+360)%360;void $('#wheel').offsetWidth;$('#wheel').style.transition='';$('#wheel').style.transform=`rotate(${wheelAngle}deg)`;
  await new Promise(r=>setTimeout(r,reduced?50:5900));
  wheelSound.finish();panel.classList.remove('is-spinning');panel.classList.add('is-revealed');drawWheel(result.candidates,result.task.id);
  $('#wheel-result').innerHTML=`${esc(result.task.icon)} ${esc(result.task.title)} <strong>+${number(result.task.points)} puan</strong>`;button.innerHTML=`${icon('check')} <span>Görevin hazır!</span>`;celebrate();
  await new Promise(r=>setTimeout(r,reduced?50:1000));
  page='profile';render();window.scrollTo({top:0,behavior:'instant'});
  openModal('Yeni görevin geldi! 🎉',`<div class="spin-prize"><span>${esc(result.task.icon)}</span><h3>${esc(result.task.title)}</h3><strong>+${number(result.task.points)} <small>puan</small></strong></div><p>${esc(result.task.description)}<br><br>Görevin sayfana kaydedildi. Bitirdiğinde ebeveynine onaya gönder.</p><div class="modal-actions"><button class="primary" data-close>Görevimi gör ${icon('arrow')}</button></div>`);
 }catch(e){wheelSound.stop();toast(e.message);await reloadState(false);}
 finally{wheelSound.stop();spinning=false;if(button.isConnected)render();}
}
function switchUser(){page='profile';render();}
root.addEventListener('change',e=>{if(['progress-date','progress-end','progress-child','progress-source'].includes(e.target.id)){if(e.target.id==='progress-date'){if(!e.target.value||!e.target.validity.valid)return;progressDate=e.target.value;if($('#progress-end'))$('#progress-end').min=progressDate;}else if(e.target.id==='progress-end'){if(!e.target.value||!e.target.validity.valid)return;progressEnd=e.target.value;}else if(e.target.id==='progress-child')progressChild=e.target.value;else progressSource=e.target.value;loadProgress();return;}if(e.target.id==='admin-person'){adminPerson=e.target.value;render();}});
root.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.action==='toggle-sound'){wheelSound.toggle();b.innerHTML=soundButton();b.setAttribute('aria-pressed',String(wheelSound.enabled));return;}if(spinning||busy)return;const d=b.dataset;if(d.deleteWish)deleteRewardRequestEditor(d.deleteWish);else if(d.action==='spin-game')spinGame();else if(d.editGames)gamesEditor(d.editGames);else if(d.assignTask)assignTaskEditor(d.assignTask,d.child);else if(d.action==='new-pool-task')parentTaskEditor();else if(d.parentAssignment)confirmParentAssignment(d.parentAssignment);else if(d.parentRoutine)confirmParentRoutine(d.child,d.parentRoutine);else if(d.action==='new-wish')requestRewardEditor();else if(d.reviewWish)reviewRewardEditor(d.reviewWish);else if(d.cancelWish)commit('cancelRewardRequest',{id:d.cancelWish},'İsteğin geri çekildi.');else if(d.progressMode){progressMode=d.progressMode;render();}else if(d.progressStep)moveProgress(Number(d.progressStep));else if(b.hasAttribute('data-progress-today')){progressDate=state.today;render();}else if(b.hasAttribute('data-progress-retry'))loadProgress();else if(d.openLetter)openLetter(d.openLetter);else if(d.completeRoutine)commit('completeRoutine',{routineId:d.completeRoutine,day:state.today},'Harika! Görevin ebeveynine gönderildi.');else if(d.action==='new-account')accountEditor();else if(d.archiveAccount)archiveAccount(d.archiveAccount);else if(d.restoreAccount)commit('restoreAccount',{id:d.restoreAccount},'Kullanıcı geri eklendi.');else if(d.routines)routinesEditor(d.routines);else if(b.hasAttribute('data-remove-photo'))commit('savePhoto',{remove:true},'Profil fotoğrafın kaldırıldı.');else if(d.adminTab){adminTab=d.adminTab;render();}else if(d.editAccount)accountEditor(d.editAccount);else if(d.review)commit('reviewAssignment',{assignmentId:d.review,decision:d.decision},d.decision==='approve'?'Onaylandı. Puan eklendi.':'Görev geri gönderildi.');else if(d.nav){e.preventDefault();page=d.nav;render();window.scrollTo({top:0,behavior:'smooth'});}else if(d.user)switchUser(d.user);else if(d.filter){filter=d.filter;render();}else if(d.wheelFilter){wheelFilter=d.wheelFilter;render();}else if(d.goal)commit('selectGoal',{userId:selected,rewardId:d.goal},'Hedefin kaydedildi. Şimdi çarkı çevir! 🎯');else if(d.cancelAssignment)confirmFamilyAction('cancelAssignment',d.cancelAssignment);else if(d.cancelCompetition)confirmFamilyAction('cancelCompetition',d.cancelCompetition);else if(d.claimCompetition)confirmFamilyAction('claimCompetition',d.claimCompetition);else if(d.complete)submitForReview(d.complete);else if(d.editTask)editor('task',d.editTask);else if(d.deleteTask)confirmDelete('task',d.deleteTask);else if(d.editReward)editor('reward',d.editReward);else if(d.deleteReward)confirmDelete('reward',d.deleteReward);else if(d.editUser)editor('user',d.editUser);else if(d.redeem)confirmReward(d.redeem);else if(d.action==='new-competition')competitionEditor();else if(d.action==='new-task')editor('task');else if(d.action==='new-reward')editor('reward');else if(d.action==='spin')spinWheel();else if(d.action==='logout'){api('logout',{}).then(()=>{state=null;init();}).catch(e=>toast(e.message));}else if(d.action==='profiles'){openModal('Bugün kim oynuyor?',`<div style="display:grid;gap:10px">${state.users.map(u=>`<button class="secondary" data-switch="${u.id}">${esc(u.avatar)} ${esc(u.name)} · ${number(u.balance)} puan</button>`).join('')}</div>`);}});
modal.addEventListener('click',e=>{if(busy)return;const close=e.target.closest('[data-close]'),profile=e.target.closest('[data-switch]');if(close)modal.close();if(profile)switchUser(profile.dataset.switch);if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
modal.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
function showLogin(){
 document.querySelector('.wish-celebration')?.remove();modal.close();clearInterval(refreshTimer);state=null;
 root.innerHTML=`<main class="login"><form class="login-box" id="login-form"><div class="brand"><span class="brand-icon">⌂</span><div>home<span>dojo</span></div></div><h1>${setupMode?'Kişisel hesaplara geçiş':'Eve hoş geldin.'}</h1><p>${setupMode?'Mevcut ev şifrenle giriş yapıp dört kişisel hesabı oluştur.':'Kendi hesabınla devam et.'}</p>${setupMode?'':'<label>Kullanıcı adı<input name="username" autocomplete="username" autocapitalize="none" required></label>'}<label>${setupMode?'Mevcut ev şifresi':'Şifre'}<input type="password" name="password" autocomplete="current-password" required></label><div class="form-error" role="alert"></div><button class="primary">${setupMode?'Kuruluma geç':'Giriş yap'} ${icon('arrow')}</button></form></main>`;
 $('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const result=await api('login',Object.fromEntries(new FormData(e.target)));csrf=result.csrf;page='profile';await init();}catch(err){const error=$('.form-error');if(error)error.textContent=err.message;}finally{button.disabled=false;}};
}
function accountSetup(profiles){
 state=null;clearInterval(refreshTimer);const defaultAdmin=profiles.find(u=>u.name.toLocaleLowerCase('tr-TR')==='baba')?.id||'';
 root.innerHTML=`<main class="account-setup"><form id="setup-accounts" class="panel"><div class="brand"><span class="brand-icon">⌂</span>homedojo</div><h1>Herkese kendi hesabı.</h1><p>Mevcut puanlar ve görevler korunur. Baba admin olur; diğer üyeler kendi sayfalarına giriş yapar.</p><label>Baba'nın mevcut profili<select name="adminId" required><option value="">Baba'ya ait profili seç</option>${profiles.map(u=>`<option value="${u.id}" ${u.id===defaultAdmin?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><div class="setup-accounts-grid">${profiles.map((u,i)=>`<fieldset><legend>${esc(u.avatar)} ${esc(u.name)}</legend><label>Görünecek isim<input name="name-${u.id}" value="${esc(u.name)}" maxlength="30" required></label><label>Kullanıcı adı<input name="username-${u.id}" pattern="[a-zA-Z0-9._-]{3,32}" autocomplete="off" placeholder="ornek: anne" required></label><label>Yeni şifre<input type="password" name="password-${u.id}" minlength="4" maxlength="72" autocomplete="new-password" required></label><label>Şifreyi tekrar yaz<input type="password" name="confirm-${u.id}" minlength="4" maxlength="72" autocomplete="new-password" required></label></fieldset>`).join('')}</div><p>Her şifre en az 4 karakter olmalı. Bu adım bir kez yapılır.</p><div class="form-error" role="alert"></div><button class="primary">Hesapları oluştur ve Baba olarak devam et</button></form></main>`;
 $('#setup-accounts').onsubmit=async e=>{e.preventDefault();const form=e.target,d=new FormData(form),error=form.querySelector('.form-error'),button=form.querySelector('button');error.textContent='';
 const accounts=profiles.map(u=>({id:u.id,name:d.get('name-'+u.id),username:d.get('username-'+u.id),password:d.get('password-'+u.id)}));
 if(accounts.some(u=>u.password!==d.get('confirm-'+u.id))){error.textContent='Şifre tekrarları eşleşmiyor.';return;}
 button.disabled=true;try{const result=await api('setupAccounts',{adminId:d.get('adminId'),accounts});csrf=result.csrf;setupMode=false;page='profile';await init();}catch(err){error.textContent=err.message;}finally{button.disabled=false;}
 };
}
async function reloadState(showError=true){try{const result=await api('state');csrf=result.csrf;if(result.setupRequired){accountSetup(result.profiles);return false;}acceptState(result.state);if(!modal.open&&!spinning){if(page==='progress'&&state.canViewProgress&&$('#progress-results'))loadProgress();else render();}return true;}catch(e){if(showError)toast(e.message);return false;}}
async function init(){try{const session=await api('session');csrf=session.csrf;setupMode=session.needsAccountSetup;if(setupMode){await reloadState();return;}if(!session.authenticated){showLogin();return;}if(await reloadState()){clearInterval(refreshTimer);refreshTimer=setInterval(()=>{if(!document.hidden&&!modal.open&&!busy&&!spinning&&page!=='account')reloadState(false);},15000);}}catch(e){root.innerHTML=`<div class="loading"><span class="brand-icon">⌂</span><p>${esc(e.message)}</p><button class="secondary" id="retry">Yeniden dene</button></div>`;$('#retry').onclick=init;}}
init();

document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state&&!busy&&!spinning&&!modal.open&&page!=='account')reloadState(false);});
